function LogFilter({ onQuery }: { onQuery: (q: string) => void }) {
  const [q, setQ] = useState("");
  // chaque frappe relance la requête réseau
  useEffect(() => { onQuery(q); }, [q, onQuery]);
  return <input value={q} onChange={(e) => setQ(e.target.value)} />;
}

